def load_exact_duplicate_index(root: Path) -> dict[str, dict[str, object]]:
    if not (root / EXACT_DUPES_JSON).exists():
        return {}
    payload = json.loads((root / EXACT_DUPES_JSON).read_text(encoding="utf-8"))
    by_path: dict[str, dict[str, object]] = {}
    for group in payload.get("groups", []):
        files = list(group.get("files", []))
        canonical = str(group["canonical_file"])
        for item in files:
            by_path[str(item["path"])] = {
                "hash": str(group["hash"]),
                "size": int(item.get("size", 0)),
                "canonical_file": canonical,
                "canonical_is_mirror": looks_like_mirror_area(canonical),
                "canonical_in_nested_subvault": any(str(entry.get("path")) == canonical and bool(entry.get("in_nested_subvault")) for entry in files),
